text:
.panel-banner-item {
  appearance: none;
  margin: var(--appmenu-button-margin);
  padding-inline: 8px;
  padding-block: calc(var(--appmenu-button-padding) + 3px);
  border-radius: var(--panel-menuitem-border-radius);
  color: var(--button-text-color);
  background-color: color-mix(in srgb, currentColor 7%, transparent);
  margin-block-end: 4px;
  font-weight: 600;

  &:not([disabled]):hover {
    background-color: var(--panel-background-color-dimmed);

    &:active {
      background-color: var(--panel-background-color-dimmed-further);
    }
  }

  & > .toolbarbutton-text {
    display: inline-block;
    padding: 0;
  }

  & > .toolbarbutton-icon {
    inline-size: 16px;
    block-size: 16px;
    /* Move the icon to appear after the text label. */
    order: 2;
  }

  &:is(
      [notificationid="update-available"],
      [notificationid="update-downloading"],
      [notificationid="update-manual"],
      [notificationid="update-other-instance"],
      [notificationid="update-restart"]
    )
    > .toolbarbutton-icon {
    background-image: url(chrome://messenger/skin/icons/app-update-badge.svg);
    background-repeat: no-repeat;
    background-position: center;
    margin-inline-start: 6px;
    -moz-context-properties: fill;
    fill: var(--color-green-60);
  }
}
